table_id`,e.`merchant_id`,e.`greed`,e.`alt_currency_id`,e.`npc_spells_id`,e.`npc_spells_effects_id`,e.`npc_faction_id`,e.`adventure_template_id`,e.`trap_template`,e.`mindmg`,e.`maxdmg`,e.`attack_count`,e.`npcspecialattks`,e.`special_abilities`,e.`aggroradius`,e.`assistradius`,e.`face`,e.`luclin_hairstyle`,e.`luclin_haircolor`,e.`luclin_eyecolor`,e.`luclin_eyecolor2`,e.`luclin_beardcolor`,e.`luclin_beard`,e.`drakkin_heritage`,e.`drakkin_tattoo`,e.`drakkin_details`,e.`armortint_id`,e.`armortint_red`,e.`armortint_green`,e.`armortint_blue`,e.`d_melee_texture1`,e.`d_melee_texture2`,e.`ammo_idfile`,e.`prim_melee_type`,e.`sec_melee_type`,e.`ranged_type`,e.`runspeed`,e.`MR`,e.`CR`,e.`DR`,e.`FR`,e.`PR`,e.`Corrup`,e.`PhR`,e.`see_invis`,e.`see_invis_undead`,e.`qglobal`,e.`AC`,e.`npc_aggro`,e.`spawn_limit`,e.`attack_speed`,e.`attack_delay`,e.`findable`,e.`STR`,e.`STA`,e.`DEX`,e.`AGI`,e.`_INT`,e.`WIS`,e.`CHA`,e.`see_hide`,e.`see_improved_hide`,e.`trackable`,e.`isbot`,e.`exclude`,e.`ATK`,e.`Accuracy`,e.`Avoidance`,e.`slow_mitigation`,e.`version`,e.`maxlevel`,e.`scalerate`,e.`private_corpse`,e.`unique_spawn_by_name`,e.`underwater`,e.`isquest`,e.`emoteid`,e.`spellscale`,e.`healscale`,e.`no_target_hotkey`,e.`raid_target`,e.`armtexture`,e.`bracertexture`,e.`handtexture`,e.`legtexture`,e.`feettexture`,e.`light`,e.`walkspeed`,e.`peqid`,e.`unique_`,e.`fixed`,e.`ignore_despawn`,e.`show_name`,e.`untargetable`,e.`charm_ac`,e.`charm_min_dmg`,e.`charm_max_dmg`,e.`charm_attack_delay`,e.`charm_accuracy_rating`,e.`charm_avoidance_rating`,e.`charm_atk`,e.`skip_global_loot`,e.`rare_spawn`,e.`stuck_behavior`,e.`model`,e.`flymode`,e.`always_aggro`,e.`exp_mod`,e.`heroic_strikethrough`,e.`faction_amount`,e.`keeps_sold_items`,e.`is_parcel_merchant`,e.`multiquest_enabled`,e.`npc_tint_id` FROM `_sunw_npc_types` e WHERE @sunderock_world_ok=1 AND NOT EXISTS(SELECT 1 FROM `npc_types` a WHERE a.`id`<=>e.`id`);
INSERT INTO `lootdrop`(`id`,`name`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`) SELECT e.`id`,e.`name`,e.`min_expansion`,e.`max_expansion`,e.`content_flags`,e.`content_flags_disabled` FROM `_sunw_lootdrop` e WHERE @sunderock_world_ok=1 AND NOT EXISTS(SELECT 1 FROM `lootdrop` a WHERE a.`id`<=>e.`id`);
INSERT INTO `lootdrop_entries`(`lootdrop_id`,`item_id`,`item_charges`,`equip_item`,`chance`,`disabled_chance`,`trivial_min_level`,`trivial_max_level`,`multiplier`,`npc_min_level`,`npc_max_level`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`) SELECT e.`lootdrop_id`,e.`item_id`,e.`item_charges`,e.`equip_item`,e.`chance`,e.`disabled_chance`,e.`trivial_min_level`,e.`trivial_max_level`,e.`multiplier`,e.`npc_min_level`,e.`npc_max_level`,e.`min_expansion`,e.`max_expansion`,e.`content_flags`,e.`content_flags_disabled` FROM `_sunw_lootdrop_entries` e WHERE @sunderock_world_ok=1 AND NOT EXISTS(SELECT 1 FROM `lootdrop_entries` a WHERE a.`lootdrop_id`<=>e.`lootdrop_id` AND a.`item_id`<=>e.`item_id`);
INSERT INTO `loottable`(`id`,`name`,`mincash`,`maxcash`,`avgcoin`,`done`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`) SELECT e.`id`,e.`name`,e.`mincash`,e.`maxcash`,e.`avgcoin`,e.`done`,e.`min_expansion`,e.`max_expansion`,e.`content_flags`,e.`content_flags_disabled` FROM `_sunw_loottable` e WHERE @sunderock_world_ok=1 AND NOT EXISTS(SELECT 1 FROM `loottable` a WHERE a.`id`<=>e.`id`);
INSERT INTO `loottable_entries`(`loottable_id`,`lootdrop_id`,`multiplier`,`droplimit`,`mindrop`,`probability`) SELECT e.`loottable_id`,e.`lootdrop_id`,e.`multiplier`,e.`droplimit`,e.`mindrop`,e.`probability` FROM `_sunw_loottable_entries` e WHERE @sunderock_world_ok=1 AND NOT EXISTS(SELECT 1 FROM `loottable_entries` a WHERE a.`loottable_id`<=>e.`loottable_id` AND a.`lootdrop_id`<=>e.`lootdrop_id`);
INSERT INTO `grid`(`id`,`zoneid`,`type`,`type2`) SELECT e.`id`,e.`zoneid`,e.`type`,e.`type2` FROM `_sunw_grid` e WHERE @sunderock_world_ok=1 AND NOT EXISTS(SELECT 1 FROM `grid` a WHERE a.`id`<=>e.`id` AND a.`zoneid`<=>e.`zoneid`);
INSERT INTO `grid_entries`(`gridid`,`zoneid`,`number`,`x`,`y`,`z`,`heading`,`pause`,`centerpoint`) SELECT e.`gridid`,e.`zoneid`,e.`number`,e.`x`,e.`y`,e.`z`,e.`heading`,e.`pause`,e.`centerpoint` FROM `_sunw_grid_entries` e WHERE @sunderock_world_ok=1 AND NOT EXISTS(SELECT 1 FROM `grid_entries` a WHERE a.`gridid`<=>e.`gridid` AND a.`zoneid`<=>e.`zoneid` AND a.`number`<=>e.`number`);
INSERT INTO `_suna_guard`VALUES(COALESCE(@sunderock_activation_ok,0));
