-- 20261105 rof2b port: sunderock - Sunderock Springs quests (15 tasks/56 objectives).
-- Source: github.com/nightstalker6669/EQEmu branch rof2-achievements,
--   extensions/rof2/achievements/content/sunderock (GPL-3.0), ported 2026-11-05.
-- Forward SQL files concatenated verbatim in install order; fail-closed
-- guards and session variables preserved. Reviewed-flag acceptance block
-- added here (upstream reconstruction defaults documented in the package's
-- provenance/ directory; see docs/rof2-zone-quests-attribution.md).
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
SET @sunderock_reviewed=1;
SET @sunderock_world_reviewed=1;
SET @sunderock_activation_reviewed=1;
-- (reviewed flags accepted: @sunderock_reviewed, @sunderock_world_reviewed, @sunderock_activation_reviewed)

-- ---- sunderock/sql/015-known-owned-activity-upgrade.sql ----
-- Correct the exact owned draft: return objective is native loot, not hail.
-- Preserve all character state. Refuse ambiguous already-credited active drafts.
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_sunu_old`;
CREATE TEMPORARY TABLE `_sunu_old` LIKE task_activities;
DROP TEMPORARY TABLE IF EXISTS `_sunu_new`;
CREATE TEMPORARY TABLE `_sunu_new` LIKE task_activities;
DROP TEMPORARY TABLE IF EXISTS `_sunu_guard`;
CREATE TEMPORARY TABLE `_sunu_guard`(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
SET @sunderock_upgrade_ok=COALESCE(@sunderock_reviewed,0)=1 AND NOT EXISTS(SELECT 1 FROM tasks WHERE id=3040704 AND BINARY title<>'The Ashengate Orders') AND (NOT EXISTS(SELECT 1 FROM task_activities a WHERE a.taskid=3040704 AND a.activityid=2) OR EXISTS(SELECT 1 FROM task_activities a WHERE a.taskid=3040704 AND a.activityid=2 AND (EXISTS(SELECT 1 FROM `_sunu_new` e WHERE a.`taskid`<=>e.`taskid` AND a.`activityid`<=>e.`activityid` AND a.`req_activity_id`<=>e.`req_activity_id` AND a.`step`<=>e.`step` AND a.`activitytype`<=>e.`activitytype` AND BINARY a.`target_name`<=>BINARY e.`target_name` AND a.`goalmethod`<=>e.`goalmethod` AND a.`goalcount`<=>e.`goalcount` AND BINARY a.`description_override`<=>BINARY e.`description_override` AND BINARY a.`npc_match_list`<=>BINARY e.`npc_match_list` AND BINARY a.`item_id_list`<=>BINARY e.`item_id_list` AND BINARY a.`item_list`<=>BINARY e.`item_list` AND a.`dz_switch_id`<=>e.`dz_switch_id` AND a.`min_x`<=>e.`min_x` AND a.`min_y`<=>e.`min_y` AND a.`min_z`<=>e.`min_z` AND a.`max_x`<=>e.`max_x` AND a.`max_y`<=>e.`max_y` AND a.`max_z`<=>e.`max_z` AND BINARY a.`skill_list`<=>BINARY e.`skill_list` AND BINARY a.`spell_list`<=>BINARY e.`spell_list` AND BINARY a.`zones`<=>BINARY e.`zones` AND a.`zone_version`<=>e.`zone_version` AND a.`optional`<=>e.`optional` AND a.`list_group`<=>e.`list_group`) OR (EXISTS(SELECT 1 FROM `_sunu_old` e WHERE a.`taskid`<=>e.`taskid` AND a.`activityid`<=>e.`activityid` AND a.`req_activity_id`<=>e.`req_activity_id` AND a.`step`<=>e.`step` AND a.`activitytype`<=>e.`activitytype` AND BINARY a.`target_name`<=>BINARY e.`target_name` AND a.`goalmethod`<=>e.`goalmethod` AND a.`goalcount`<=>e.`goalcount` AND BINARY a.`description_override`<=>BINARY e.`description_override` AND BINARY a.`npc_match_list`<=>BINARY e.`npc_match_list` AND BINARY a.`item_id_list`<=>BINARY e.`item_id_list` AND BINARY a.`item_list`<=>BINARY e.`item_list` AND a.`dz_switch_id`<=>e.`dz_switch_id` AND a.`min_x`<=>e.`min_x` AND a.`min_y`<=>e.`min_y` AND a.`min_z`<=>e.`min_z` AND a.`max_x`<=>e.`max_x` AND a.`max_y`<=>e.`max_y` AND a.`max_z`<=>e.`max_z` AND BINARY a.`skill_list`<=>BINARY e.`skill_list` AND BINARY a.`spell_list`<=>BINARY e.`spell_list` AND BINARY a.`zones`<=>BINARY e.`zones` AND a.`zone_version`<=>e.`zone_version` AND a.`optional`<=>e.`optional` AND a.`list_group`<=>e.`list_group`) AND NOT EXISTS(SELECT 1 FROM character_activities WHERE taskid=3040704 AND activityid=2 AND donecount>0)))));
UPDATE task_activities a SET `step`=0,`activitytype`=3,`npc_match_list`='',`item_id_list`=CONVERT(0x3835363938 USING utf8mb4) WHERE @sunderock_upgrade_ok=1 AND a.taskid=3040704 AND a.activityid=2 AND EXISTS(SELECT 1 FROM `_sunu_old` e WHERE a.`taskid`<=>e.`taskid` AND a.`activityid`<=>e.`activityid` AND a.`req_activity_id`<=>e.`req_activity_id` AND a.`step`<=>e.`step` AND a.`activitytype`<=>e.`activitytype` AND BINARY a.`target_name`<=>BINARY e.`target_name` AND a.`goalmethod`<=>e.`goalmethod` AND a.`goalcount`<=>e.`goalcount` AND BINARY a.`description_override`<=>BINARY e.`description_override` AND BINARY a.`npc_match_list`<=>BINARY e.`npc_match_list` AND BINARY a.`item_id_list`<=>BINARY e.`item_id_list` AND BINARY a.`item_list`<=>BINARY e.`item_list` AND a.`dz_switch_id`<=>e.`dz_switch_id` AND a.`min_x`<=>e.`min_x` AND a.`min_y`<=>e.`min_y` AND a.`min_z`<=>e.`min_z` AND a.`max_x`<=>e.`max_x` AND a.`max_y`<=>e.`max_y` AND a.`max_z`<=>e.`max_z` AND BINARY a.`skill_list`<=>BINARY e.`skill_list` AND BINARY a.`spell_list`<=>BINARY e.`spell_list` AND BINARY a.`zones`<=>BINARY e.`zones` AND a.`zone_version`<=>e.`zone_version` AND a.`optional`<=>e.`optional` AND a.`list_group`<=>e.`list_group`);
COMMIT;

-- ---- sunderock/sql/020-journal-rewards.disabled.sql ----
-- OFFLINE disabled Sunderock journal/reward payload; world-acquisition dependencies remain separate.
-- MariaDB only. Review/protect writer state and backups before deliberate use. Never use --force.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_sun_tasks`;
CREATE TEMPORARY TABLE `_sun_tasks` LIKE `tasks`;
DROP TEMPORARY TABLE IF EXISTS `_sun_task_activities`;
CREATE TEMPORARY TABLE `_sun_task_activities` LIKE `task_activities`;
DROP TEMPORARY TABLE IF EXISTS `_sun_achievement_criteria`;
CREATE TEMPORARY TABLE `_sun_achievement_criteria` LIKE `achievement_criteria`;
DROP TEMPORARY TABLE IF EXISTS `_sun_reward_sets`;
CREATE TEMPORARY TABLE `_sun_reward_sets` LIKE `reward_sets`;
DROP TEMPORARY TABLE IF EXISTS `_sun_reward_sources`;
CREATE TEMPORARY TABLE `_sun_reward_sources` LIKE `reward_sources`;
DROP TEMPORARY TABLE IF EXISTS `_sun_rewards`;
CREATE TEMPORARY TABLE `_sun_rewards` LIKE `rewards`;
DROP TEMPORARY TABLE IF EXISTS `_sun_reward_options`;
CREATE TEMPORARY TABLE `_sun_reward_options` LIKE `reward_options`;
DROP TEMPORARY TABLE IF EXISTS `_sun_reward_option_entries`;
CREATE TEMPORARY TABLE `_sun_reward_option_entries` LIKE `reward_option_entries`;
DROP TEMPORARY TABLE IF EXISTS `_sun_guard`;
CREATE TEMPORARY TABLE `_sun_guard`(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
SET @sunderock_ok=COALESCE(@sunderock_reviewed,0)=1 AND
((SELECT COUNT(*)FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN(CONVERT(0x7461736b73 USING utf8mb4),CONVERT(0x7461736b5f61637469766974696573 USING utf8mb4),CONVERT(0x616368696576656d656e745f6372697465726961 USING utf8mb4),CONVERT(0x7265776172645f73657473 USING utf8mb4),CONVERT(0x7265776172645f736f7572636573 USING utf8mb4),CONVERT(0x72657761726473 USING utf8mb4),CONVERT(0x7265776172645f6f7074696f6e73 USING utf8mb4),CONVERT(0x7265776172645f6f7074696f6e5f656e7472696573 USING utf8mb4)) AND ENGINE='InnoDB')=8)
