 AND (NOT EXISTS(SELECT 1 FROM `task_activities` a WHERE (a.taskid IN(3040701,3040702,3040703,3040704,3040705,3040706,3040707,3040708,3040709,3040710,3040711,3040712,3040713,3040714,3040715)) AND NOT EXISTS(SELECT 1 FROM `_sun_task_activities` e WHERE a.`taskid`<=>e.`taskid` AND a.`activityid`<=>e.`activityid` AND a.`req_activity_id`<=>e.`req_activity_id` AND a.`step`<=>e.`step` AND a.`activitytype`<=>e.`activitytype` AND a.`target_name`<=>e.`target_name` AND a.`goalmethod`<=>e.`goalmethod` AND a.`goalcount`<=>e.`goalcount` AND a.`description_override`<=>e.`description_override` AND a.`npc_match_list`<=>e.`npc_match_list` AND a.`item_id_list`<=>e.`item_id_list` AND a.`zones`<=>e.`zones` AND a.`spell_list`<=>e.`spell_list` AND a.`optional`<=>e.`optional` AND a.`min_x`<=>e.`min_x` AND a.`max_x`<=>e.`max_x` AND a.`min_y`<=>e.`min_y` AND a.`max_y`<=>e.`max_y` AND a.`min_z`<=>e.`min_z` AND a.`max_z`<=>e.`max_z`)))
