START TRANSACTION;
SET @sunderock_activation_ok=COALESCE(@sunderock_activation_reviewed,0)=1 AND COALESCE(@sunderock_ok,0)=1 AND COALESCE(@sunderock_world_ok,0)=1 AND
((SELECT COUNT(*)FROM tasks WHERE id IN(3040701,3040702,3040703,3040704,3040705,3040706,3040707,3040708,3040709,3040710,3040711,3040712,3040713,3040714,3040715))=15)
 AND ((SELECT COUNT(*)FROM task_activities WHERE taskid IN(3040701,3040702,3040703,3040704,3040705,3040706,3040707,3040708,3040709,3040710,3040711,3040712,3040713,3040714,3040715))=56)
 AND ((SELECT COUNT(*)FROM achievement_criteria WHERE component_type=1 AND event_type=4 AND progress_mode=3 AND target_id IN(3040701,3040702,3040703,3040704,3040705,3040706,3040707,3040708,3040709,3040710,3040711,3040712,3040713,3040714,3040715))=15)
 AND ((SELECT COUNT(*)FROM achievements WHERE id IN(500070200,500070300,500070400,500070500))=4)
 AND ((SELECT COUNT(*)FROM reward_sets WHERE reward_set_id IN(3040705,3040710,3040712,3040791,3040792,3040793,3040794))=7)
 AND ((SELECT COUNT(*)FROM reward_options WHERE reward_set_id IN(3040705,3040710,3040712,3040791,3040792,3040793,3040794))=22)
 AND ((SELECT COUNT(*)FROM reward_option_entries WHERE reward_set_id IN(3040705,3040710,3040712,3040791,3040792,3040793,3040794))=24)
 AND ((SELECT COUNT(*)FROM rewards WHERE reward_id IN(304070510,304070520,304070530,304070540,304070550,304071010,304071020,304071030,304071040,304071210,304071220,304071230,304079110,304079120,304079130,304079140,304079210,304079220,304079310,304079311,304079320,304079321,304079410,304079420))=24)
 AND (EXISTS(SELECT 1 FROM npc_types WHERE id=403024 AND class=62 AND loottable_id=3040713))
 AND (EXISTS(SELECT 1 FROM npc_types WHERE id=403197 AND loottable_id=3040708))
 AND (EXISTS(SELECT 1 FROM npc_types WHERE id=403199 AND loottable_id=3040704 AND special_abilities='16,1'))
 AND ((SELECT COUNT(*)FROM npc_types WHERE id IN(403091,403198) AND special_abilities='16,1')=2)
 AND (EXISTS(SELECT 1 FROM npc_types WHERE id=403900 AND name='an_oozebud'))
 AND (EXISTS(SELECT 1 FROM spawn2 WHERE id=114523 AND pathgrid=3040701))
 AND ((SELECT COUNT(*)FROM grid_entries WHERE zoneid=403 AND gridid=3040701)=221);
UPDATE `tasks` SET enabled=1 WHERE @sunderock_activation_ok=1 AND (id IN(3040701,3040702,3040703,3040704,3040705,3040706,3040707,3040708,3040709,3040710,3040711,3040712,3040713,3040714,3040715));
UPDATE `achievement_criteria` SET enabled=1 WHERE @sunderock_activation_ok=1 AND (component_type=1 AND event_type=4 AND target_id IN(3040701,3040702,3040703,3040704,3040705,3040706,3040707,3040708,3040709,3040710,3040711,3040712,3040713,3040714,3040715));
UPDATE `achievements` SET enabled=1 WHERE @sunderock_activation_ok=1 AND (id IN(500070200,500070300,500070400,500070500));
UPDATE `reward_sets` SET enabled=1 WHERE @sunderock_activation_ok=1 AND (reward_set_id IN(3040705,3040710,3040712,3040791,3040792,3040793,3040794));
UPDATE `reward_sources` SET enabled=1 WHERE @sunderock_activation_ok=1 AND (reward_set_id IN(3040705,3040710,3040712,3040791,3040792,3040793,3040794));
UPDATE `reward_options` SET enabled=1 WHERE @sunderock_activation_ok=1 AND (reward_set_id IN(3040705,3040710,3040712,3040791,3040792,3040793,3040794));
UPDATE `rewards` SET enabled=1 WHERE @sunderock_activation_ok=1 AND (reward_id IN(304070510,304070520,304070530,304070540,304070550,304071010,304071020,304071030,304071040,304071210,304071220,304071230,304079110,304079120,304079130,304079140,304079210,304079220,304079310,304079311,304079320,304079321,304079410,304079420));
COMMIT;
